const bankaSdk = {
  async odemeAl(tutar) {
    // Gerçek bankanın odemeAl fonksiyonu TRX- ve 8 haneli rakam döndürür
    const rastgeleNumara = Math.floor(Math.random() * 100000000)
    return `TRX-${rastgeleNumara.toString().padStart(8, '0')}`
  }
};

const { odemeAl } = bankaSdk;

export async function odemeYap(tutar) {
  return await odemeAl(tutar)
}"}
